SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2020.Year, Станции2020.NUST, Станции2020.nr, Станции2020.E, Станции2020.EOTP, Станции2020.EURT, Станции2020.EUST, Станции2020.Q, Станции2020.TURT, Станции2020.TUST, Станции2020.B, Станции2020.GAZ, Доп_угли2020.gaz_prir, Доп_угли2020.gazpp, Станции2020.MAZUT, Доп_угли2020.maztop, Доп_угли2020.gtt, Доп_угли2020.nft_proch, Доп_угли2020.disel, Станции2020.TORF, Станции2020.SLAN, Станции2020.ISK_GAZ, Доп_угли2020.domen_g, Доп_угли2020.koks_g, Доп_угли2020.prochgaz, Станции2020.PROCH, Доп_угли2020.tvproch, Доп_угли2020.szh_gaz, Доп_угли2020.inoe, Станции2020.UGOL, Станции2020.DON, Станции2020.PODM, Станции2020.PECH, Доп_угли2020.intin, Доп_угли2020.vork, Станции2020.ARKT, Станции2020.KUZN, Доп_угли2020.kuzngd, Доп_угли2020.kuznt, Доп_угли2020.kuznss, Доп_угли2020.kuznun, Станции2020.URAL, Доп_угли2020.sver, Доп_угли2020.chel, Доп_угли2020.kizel, Станции2020.BASHK, Станции2020.KAN, Доп_угли2020.nazar, Доп_угли2020.ibor, Доп_угли2020.berez, Доп_угли2020.per, Доп_угли2020.irbei, Доп_угли2020.kansk, Станции2020.TUNG, Доп_угли2020.jer, Доп_угли2020.karab, Станции2020.IRKUT, Доп_угли2020.azey, Доп_угли2020.mug, Доп_угли2020.cher, Станции2020.HAK, Станции2020.TUV, Станции2020.BUR, Доп_угли2020.gusin, Доп_угли2020.tugn, Доп_угли2020.okino, Станции2020.CHIT, Доп_угли2020.har, Доп_угли2020.urt, Доп_угли2020.tataur, Доп_угли2020.tarbag, Доп_угли2020.zab_kam, Станции2020.YAKUT, Доп_угли2020.neru, Доп_угли2020.zyryan, Доп_угли2020.pyak, Станции2020.AMUR, Доп_угли2020.rai, Доп_угли2020.erk, Доп_угли2020.ogodj, Станции2020.URG, Станции2020.USHUM, Станции2020.PRIM, Доп_угли2020.bikin, Доп_угли2020.razdol, Доп_угли2020.hankai, Станции2020.MAG, Станции2020.SAH, Станции2020.KAMCH, Станции2020.CHUKOT, Доп_угли2020.anad, Доп_угли2020.bering, Станции2020.KAZAH, Доп_угли2020.ekib, Доп_угли2020.maikub, Доп_угли2020.karag, Доп_угли2020.karajyra, Доп_угли2020.teniz, Станции2020.QOTR, Станции2020.SNK, Станции2020.EWTP, Станции2020.NT, Станции2020.OBOR, Станции2020.VED, Станции2020.OBL, Станции2020.DEP, Станции2020.OES, Станции2020.ER, Станции2020.NUMB1120, Имена_станций.Ведомство AS вед, IIf([вед]=1 Or [вед]=4,1,IIf([вед]=2 Or [вед]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Имена_станций.BE, имена_ГК.name AS namegk, [Филиалы ГК].name AS filial, IIf([OBOR]=20 Or [OBOR]=90,"ГТУ",IIf([OBOR]=21 Or [OBOR]=91,"ПГУ",IIf([OBOR]=22,"Диз",IIf([OBOR]=23,"ГУБТ",IIf([OBOR]=24 Or [OBOR]=89,"ГПА","ПСУ"))))) AS тип, Станции2020.SNt, Имена_станций.n1 AS [мощность блока], IIf([B]>0,[gaz_prir]/[B]*100,0) AS dolya_gaz_prir, IIf([B]>0,[gazpp]/[B]*100,0) AS dolya_gazpp, IIf([B]>0,[UGOL]/[B]*100,0) AS dolya_ugol, IIf([B]>0,[MAZUT]/[B]*100,0) AS dolya_mazut, IIf([B]>0,[TORF]/[B]*100,0) AS dolya_torf, IIf([B]>0,[SLAN]/[B]*100,0) AS dolya_slan, IIf([B]>0,[PROCH]/[B]*100,0) AS dolya_proch, IIf([E]>0,[EWTP]/[E]*100,0) AS dolya_ewtp, IIf([Q]>0,[QOTR]/[Q]*100,0) AS dolya_qotr, IIf([B]>0 And [domen_g]>0,[domen_g]/[B]*100,0) AS dolya_domen_g, IIf([B]>0 And [koks_g]>0,[koks_g]/[B]*100,0) AS dolya_koks_g, IIf([B]>0 And [prochgaz]>0,[prochgaz]/[B]*100,0) AS dolya_prochgaz, IIf([B]>0,IIf([dolya_gaz_prir]>=50,"gaz_prir",IIf([dolya_gazpp]>=50,"gazpp",IIf([dolya_domen_g]>=50,"domen_g",IIf([dolya_koks_g]>=50,"koks_g",IIf([dolya_prochgaz]>=50,"prochgaz",IIf([dolya_ugol]>=50,"ugol",IIf([dolya_mazut]>=50,"neftetopl","prochee"))))))),"net topliva") AS nov_Belyaev, [EUST]/[B] AS [dolya topl na ee], [TUST]/[B] AS [dolya topl na q], Имена_областей.Terr_Belyaev, IIf([E]>0,([E]-[EOTP])/[E]*100,0) AS [%_sn], IIf([Имена_станций.BE]=9,"Пром.предпр.","Минэнерго") AS BLST_BE, IIf([Ведомство]=1,"Минэнерго","Пром.предпр.") AS BLST_V, IIf([вед]=1,"Минэнерго","Пром.предпр.") AS BLST_ved
FROM ((Имена_станций INNER JOIN (Имена_областей RIGHT JOIN (Имена_ОЭС INNER JOIN (Станции2020 LEFT JOIN Доп_угли2020 ON (Станции2020.NUMB1120 = Доп_угли2020.NUMB1120) AND (Станции2020.YEAR = Доп_угли2020.YEAR)) ON Имена_ОЭС.oes = Станции2020.OES) ON Имена_областей.OBL = Станции2020.OBL) ON Имена_станций.NUMB = Станции2020.NUMB1120) LEFT JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) INNER JOIN [Филиалы ГК] ON Имена_станций.GKF = [Филиалы ГК].code;
